const QUEUE_SORT_KEYS=new Set(['folder_created_desc','folder_created_asc','folder_modified_desc','source_modified_desc','name_asc','name_desc']);
const storedQueueSort=localStorage.getItem('autoslice.subtitle-queue-sort');
const SUBTITLE_ROOT_STORAGE_KEY='autoslice.subtitle-root-dir';
const SUBTITLE_STYLE_STORAGE_KEY='autoslice.subtitle-style';
const SUBTITLE_EXPORT_STORAGE_KEY='autoslice.subtitle-export';
const SUBTITLE_EXTRA_GLOSSARY_STORAGE_KEY='autoslice.subtitle-extra-glossary';
const state={pairs:[],selectedIndex:-1,queueSort:QUEUE_SORT_KEYS.has(storedQueueSort)?storedQueueSort:'folder_created_desc',sourceCues:[],edited:new Map(),suggestions:new Map(),ignoredSuggestions:new Set(),suggestionUndoStack:[],aiApplied:new Set(),protectedEdits:new Set(),deleted:new Set(),deletedSnapshots:new Map(),deleteSelection:new Set(),mergePrevious:new Map(),mergeOverrides:new Map(),timeOverrides:new Map(),selectedCueIndex:null,qualityIgnored:new Set(),qualityActions:[],qualityActionSerial:0,qualityRenderTimer:null,correctedPath:'',referenceTitles:null,reviewProfile:null,extraGlossary:[],profileKnownPairs:new Set(),profileAddedPairs:new Set(),filter:'all',defaults:null,previewUrl:'',sse:null,sseReconnectTimer:null,taskEvents:new Map(),taskContexts:new Map(),selectionVersion:0,busy:false};
const queueNameCollator=new Intl.Collator('zh-CN',{numeric:true,sensitivity:'base'});

function esc(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
async function jsonRequest(url,options={}){const response=await fetch(url,{headers:{'Content-Type':'application/json'},...options});const data=await response.json();if(!response.ok||data.error){const error=new Error(data.error||`请求失败 ${response.status}`);error.payload=data;error.status=response.status;throw error;}return data;}
function selectedPair(){return state.selectedIndex>=0?state.pairs[state.selectedIndex]:null;}
function setTask(message,type=''){const el=document.getElementById('taskStatus');el.textContent=message;el.className=`task-status ${type}`.trim();}
function renderReviewDictionary(profile=null){state.reviewProfile=profile&&typeof profile==='object'?profile:null;state.profileKnownPairs=new Set((Array.isArray(state.reviewProfile?.replacements)?state.reviewProfile.replacements:[]).filter(item=>Array.isArray(item)&&item.length===2).map(item=>JSON.stringify([String(item[0]),String(item[1])] )));const box=document.getElementById('reviewDictionary');if(!box)return;const label=state.reviewProfile?.label||state.reviewProfile?.streamer_profile_label;const profileId=state.reviewProfile?.id||state.reviewProfile?.streamer_profile_id;const summary=box.querySelector('[data-review-summary]');if(!label){if(summary)summary.textContent='点击 AI 检查后自动识别当前主播并加载专名规则';return;}const glossaryCount=Number(state.reviewProfile.glossary_count)||0;const defaultCount=Number(state.reviewProfile.default_glossary_count);const extraCount=Number(state.reviewProfile.extra_glossary_count);const replacementCount=Number(state.reviewProfile.replacement_count)||0;const identity=profileId?`${label}（${profileId}）`:label;const defaultText=Number.isFinite(defaultCount)?`默认 ${defaultCount} 个`:'';const extraText=Number.isFinite(extraCount)?`本视频新增 ${extraCount} 个`:'';if(summary)summary.textContent=`已识别：${identity} · ${defaultText} · ${extraText} · 共 ${glossaryCount} 个专名 · ${replacementCount} 条固定纠错`;const addButton=box.querySelector('[data-profile-write-hint]');if(addButton)addButton.hidden=state.reviewProfile.profile_write_available!==true;}
function renderReferenceTitles(){const recommended=document.getElementById('recommendedTitle');const candidates=document.getElementById('titleCandidates');const reason=document.getElementById('titleReason');const result=state.referenceTitles;if(!result){recommended.textContent='尚未生成';recommended.className='title-recommended empty';candidates.hidden=true;candidates.innerHTML='';reason.hidden=true;reason.textContent='';updateActionState();return;}recommended.textContent=result.recommended_title||'未生成有效标题';recommended.className='title-recommended';const values=Array.isArray(result.candidates)?result.candidates:[];candidates.innerHTML=values.map((title,index)=>`<div class="title-candidate"><strong>${index+1}</strong><span>${esc(title)}</span></div>`).join('');candidates.hidden=!values.length;reason.textContent=result.reason?`推荐理由：${result.reason}`:'';reason.hidden=!result.reason;updateActionState();}
function updateActionState(){const pair=selectedPair();const subtitleReady=Boolean(pair?.has_source_srt&&!pair.subtitle_error);const savedSubtitleReady=Boolean(pair?.has_corrected_srt&&state.correctedPath);const transcriptionActive=pair?.transcription_status==='queued'||pair?.transcription_status==='running';const transcribeDisabled=state.busy||!pair||!pair.needs_transcription||transcriptionActive;document.getElementById('transcribeButton').disabled=transcribeDisabled;document.getElementById('foregroundOnly').disabled=transcribeDisabled;document.getElementById('reflowButton').disabled=state.busy||!pair?.can_reflow_srt;const extraGlossary=document.getElementById('extraGlossary');if(extraGlossary)extraGlossary.disabled=state.busy||!pair;['reviewButton','forceReviewButton','saveButton','previewButton'].forEach(id=>{document.getElementById(id).disabled=state.busy||!subtitleReady;});document.getElementById('renderButton').disabled=state.busy||!savedSubtitleReady;document.getElementById('generateTitleButton').disabled=state.busy||!savedSubtitleReady;document.getElementById('copyTitleButton').disabled=state.busy||!state.referenceTitles?.recommended_title;const batchEntries=visibleSuggestionEntries();document.getElementById('acceptSuggestionsButton').disabled=state.busy||!batchEntries.length;document.getElementById('ignoreSuggestionsButton').disabled=state.busy||!batchEntries.length;document.getElementById('undoSuggestionButton').disabled=state.busy||!state.suggestionUndoStack.length;}
function setBusy(busy){state.busy=Boolean(busy);document.getElementById('scanButton').disabled=state.busy;document.getElementById('rootDir').disabled=state.busy;document.getElementById('queueSort').disabled=state.busy;document.querySelectorAll('.queue-item').forEach(el=>{el.disabled=state.busy;});updateActionState();}

function styleValues(){return{font_name:'Noto Sans S Chinese Black',font_size:Number(document.getElementById('fontSize').value),font_color:document.getElementById('fontColor').value.replace('#',''),outline_color:document.getElementById('outlineColor').value.replace('#',''),outline_width:Number(document.getElementById('outlineWidth').value),x:Number(document.getElementById('positionX').value),y:Number(document.getElementById('positionY').value),shadow:0};}
function exportValues(){return{width:1920,height:1080,bitrate_kbps:Number(document.getElementById('bitrate').value),rate_control:'vbr',codec:'h264',container:'mp4',fps:Number(document.getElementById('fps').value),color_space:'bt709',color_range:'tv',audio:'copy'};}
function loadStoredObject(key){try{const value=JSON.parse(localStorage.getItem(key)||'null');return value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch(error){return{};}}
function normaliseExtraGlossary(value){const values=Array.isArray(value)?value:String(value??'').split(/[\n,，、;；]+/);return [...new Set(values.map(item=>String(item??'').trim()).filter(Boolean).filter(item=>item.length<=100))].slice(0,100);}
function pairStorageKey(pair){return String(pair?.id||pair?.video_path||pair?.srt_path||'').trim();}
function loadExtraGlossary(pair){const store=loadStoredObject(SUBTITLE_EXTRA_GLOSSARY_STORAGE_KEY);state.extraGlossary=normaliseExtraGlossary(store[pairStorageKey(pair)]);const input=document.getElementById('extraGlossary');if(input)input.value=state.extraGlossary.join('\n');const count=document.getElementById('extraGlossaryCount');if(count)count.textContent=String(state.extraGlossary.length);}
function persistExtraGlossary(value){const pair=selectedPair();if(!pair)return;state.extraGlossary=normaliseExtraGlossary(value);try{const store=loadStoredObject(SUBTITLE_EXTRA_GLOSSARY_STORAGE_KEY);store[pairStorageKey(pair)]=state.extraGlossary;localStorage.setItem(SUBTITLE_EXTRA_GLOSSARY_STORAGE_KEY,JSON.stringify(store));}catch(error){}const count=document.getElementById('extraGlossaryCount');if(count)count.textContent=String(state.extraGlossary.length);}
function numberOverride(value,min,max){const number=Number(value);return Number.isFinite(number)&&number>=min&&number<=max?number:null;}
function colorOverride(value){const color=String(value??'').replace(/^#/,'');return/^[0-9a-fA-F]{6}$/.test(color)?color.toLowerCase():null;}
function storedStyleOverrides(){const raw=loadStoredObject(SUBTITLE_STYLE_STORAGE_KEY),result={};const fontSize=numberOverride(raw.font_size,1,30),outlineWidth=numberOverride(raw.outline_width,0,100),x=numberOverride(raw.x,-1000,1000),y=numberOverride(raw.y,-1000,1000),fontColor=colorOverride(raw.font_color),outlineColor=colorOverride(raw.outline_color);if(fontSize!==null)result.font_size=fontSize;if(outlineWidth!==null)result.outline_width=outlineWidth;if(x!==null)result.x=x;if(y!==null)result.y=y;if(fontColor)result.font_color=fontColor;if(outlineColor)result.outline_color=outlineColor;return result;}
function storedExportOverrides(){const raw=loadStoredObject(SUBTITLE_EXPORT_STORAGE_KEY),result={};const bitrate=numberOverride(raw.bitrate_kbps,500,100000),fps=numberOverride(raw.fps,1,240);if(bitrate!==null)result.bitrate_kbps=bitrate;if(fps!==null)result.fps=fps;return result;}
function persistSubtitleSettings(){try{const style=styleValues(),exp=exportValues();localStorage.setItem(SUBTITLE_STYLE_STORAGE_KEY,JSON.stringify({font_size:style.font_size,font_color:style.font_color,outline_color:style.outline_color,outline_width:style.outline_width,x:style.x,y:style.y}));localStorage.setItem(SUBTITLE_EXPORT_STORAGE_KEY,JSON.stringify({bitrate_kbps:exp.bitrate_kbps,fps:exp.fps}));}catch(error){/* 隐私模式或浏览器禁用存储时仍允许正常校对和压制。 */}}

async function loadDefaults(){try{const data=await jsonRequest('/api/subtitles/defaults');state.defaults=data;const font=data.font||{};const el=document.getElementById('fontStatus');el.textContent=font.available?`${font.requested} → ${font.resolved}`:`字体不可用：${font.resolved||'未解析'}`;el.className=`font-status ${font.available?'ok':''}`;applyDefaults(data);}catch(error){setTask(error.message,'error');}}
async function loadAsrStatus(){const box=document.getElementById('asrGuidance');try{const data=await jsonRequest('/api/asr-status');box.querySelector('strong').textContent=`${data.display_name} · ${data.device}`;box.querySelector('.asr-guidance-copy span').textContent=[data.recommendation,data.foreground_filter_hint,data.hotword_hint,data.correction_hint].filter(Boolean).join(' ');box.classList.toggle('warning',Boolean(data.needs_setup));box.classList.toggle('success',Boolean(data.recommended));}catch(error){box.querySelector('strong').textContent='FunASR 状态读取失败';box.querySelector('.asr-guidance-copy span').textContent=error.message;box.classList.add('warning');}}
function applyDefaults(data){const style={...(data.style||{}),...storedStyleOverrides()},exp={...(data.export||{}),...storedExportOverrides()};let remembered='';try{remembered=localStorage.getItem(SUBTITLE_ROOT_STORAGE_KEY)||''}catch(error){}document.getElementById('rootDir').value=remembered||data.submission_dir||'submissions';document.getElementById('fontSize').value=style.font_size??20;setColor('fontColor',style.font_color||'ffffff');setColor('outlineColor',style.outline_color||'d06e95');document.getElementById('outlineWidth').value=style.outline_width??100;document.getElementById('positionX').value=style.x??0;document.getElementById('positionY').value=style.y??-788;document.getElementById('bitrate').value=exp.bitrate_kbps??8000;document.getElementById('fps').value=exp.fps??60;persistSubtitleSettings();}
function setColor(id,value){const clean=String(value).replace('#','').toLowerCase();document.getElementById(id).value=clean;document.getElementById(`${id}Picker`).value=`#${clean}`;}

function compareQueueTime(left,right,key,descending){const a=Number(left[key])||0;const b=Number(right[key])||0;if(a===b)return 0;if(!a)return 1;if(!b)return-1;return descending?b-a:a-b;}
function comparePairs(left,right){let result=0;if(state.queueSort==='folder_created_desc'||state.queueSort==='folder_created_asc'){result=compareQueueTime(left,right,'folder_created_at',state.queueSort.endsWith('_desc'));if(!result)result=compareQueueTime(left,right,'source_created_at',state.queueSort.endsWith('_desc'));}else if(state.queueSort==='folder_modified_desc'){result=compareQueueTime(left,right,'folder_modified_at',true);}else if(state.queueSort==='source_modified_desc'){result=compareQueueTime(left,right,'source_modified_at',true);}else{result=queueNameCollator.compare(`${left.title}\n${left.video_name}`,`${right.title}\n${right.video_name}`);if(state.queueSort==='name_desc')result=-result;}return result||queueNameCollator.compare(left.directory,right.directory);}
function sortPairs(){const selectedId=selectedPair()?.id||null;state.pairs.sort(comparePairs);state.selectedIndex=selectedId?state.pairs.findIndex(pair=>pair.id===selectedId):-1;}
async function scan(){setBusy(true);setTask('扫描投稿目录...');const root=document.getElementById('rootDir').value;try{localStorage.setItem(SUBTITLE_ROOT_STORAGE_KEY,root)}catch(error){}try{const data=await jsonRequest('/api/subtitles/scan',{method:'POST',body:JSON.stringify({root_dir:root})});state.pairs=data.pairs||[];state.selectedIndex=-1;sortPairs();clearEditor();renderQueue();reapplyKnownTaskStates();setTask(`找到 ${data.count} 组投稿`,'done');}catch(error){setTask(`扫描失败：${error.message}`,'error');}finally{setBusy(false);}}
function subtitleQueueBadge(pair){if(pair.needs_transcription){if(pair.transcription_status==='running')return{label:'识别中',tone:'warn'};if(pair.transcription_status==='queued')return{label:'排队中',tone:'warn'};if(pair.transcription_status==='interrupted')return{label:'识别中断',tone:'warn'};if(pair.transcription_status==='error')return{label:'识别失败，可重试',tone:'warn'};return{label:'待识别',tone:'warn'};}if(pair.subtitle_error)return{label:'字幕异常',tone:'warn'};return{label:`${pair.cue_count} 条字幕`,tone:'ok'};}
function renderQueue(){const queue=document.getElementById('queue');document.getElementById('queueCount').textContent=`${state.pairs.length} 组投稿`;if(!state.pairs.length){queue.innerHTML='<div class="queue-empty">没有找到投稿视频</div>';updateActionState();return;}queue.innerHTML=state.pairs.map((pair,index)=>{const subtitleBadge=subtitleQueueBadge(pair);const subtitleState=pair.needs_transcription?'无字幕':pair.has_corrected_srt?'已校对':'原字幕';return `<button type="button" class="queue-item ${index===state.selectedIndex?'active':''}" data-index="${index}" title="${esc(`${pair.title}\n${pair.srt_path||pair.video_path||pair.directory||''}`)}" ${state.busy?'disabled':''}><span class="queue-title">${esc(pair.title)}</span><span class="queue-meta"><span class="badge ${subtitleBadge.tone}">${subtitleBadge.label}</span><span class="badge ${pair.has_corrected_srt?'ok':''}">${subtitleState}</span><span class="badge ${pair.has_output_video?'ok':''}">${pair.has_output_video?'已压制':'未压制'}</span></span></button>`;}).join('');queue.querySelectorAll('.queue-item').forEach(el=>el.addEventListener('click',()=>selectPair(Number(el.dataset.index))));updateActionState();}
function clearEditor(){state.selectionVersion+=1;cancelScheduledQualityRender();clearPreview();state.sourceCues=[];state.edited.clear();state.suggestions.clear();state.ignoredSuggestions.clear();state.suggestionUndoStack=[];state.aiApplied.clear();state.protectedEdits.clear();state.deleted.clear();state.deletedSnapshots.clear();state.deleteSelection.clear();state.mergePrevious.clear();state.mergeOverrides.clear();state.timeOverrides.clear();state.selectedCueIndex=null;state.qualityIgnored.clear();state.qualityActions=[];state.qualityActionSerial=0;state.correctedPath='';state.extraGlossary=[];const input=document.getElementById('extraGlossary');if(input)input.value='';const count=document.getElementById('extraGlossaryCount');if(count)count.textContent='0';renderReviewDictionary();document.getElementById('editorTitle').textContent='请选择投稿';document.getElementById('editorTitle').removeAttribute('title');document.getElementById('editorPath').textContent='';document.getElementById('editorPath').removeAttribute('title');document.getElementById('cueList').innerHTML='<div class="queue-empty">选择左侧投稿后加载字幕</div>';document.getElementById('artifactPath').textContent='尚未生成校对字幕';renderSuggestionTools();renderQualityList();setTask('等待选择投稿');updateChangeCount();updateActionState();}

function sameCueTimeline(left,right){return Number(left.index)===Number(right.index)&&left.start===right.start&&left.end===right.end&&String(left.settings||'')===String(right.settings||'');}
function correctedTimelineMatches(source,corrected){if(!corrected.length||corrected.length>source.length)return false;let sourceCursor=0;for(const correctedCue of corrected){let matchedIndex=-1;for(let index=sourceCursor;index<source.length;index+=1){if(sameCueTimeline(source[index],correctedCue)){matchedIndex=index;break;}}if(matchedIndex<0)return false;sourceCursor=matchedIndex+1;}return true;}
function resizeCueTextarea(textarea){textarea.style.height='auto';textarea.style.height=`${Math.max(44,textarea.scrollHeight+2)}px`;}
function sourceText(index){return state.sourceCues.find(cue=>cue.index===index)?.text??'';}

function normaliseWindowsPath(value){return String(value||'').replace(/\//g,'\\').toLowerCase();}
function registerTask(taskId,context){if(!taskId)return;state.taskContexts.set(taskId,context);const pending=state.taskEvents.get(taskId);if(pending)handleTask(pending);}
function taskPair(context){return state.pairs.find(pair=>pair.id===context?.pairId)||null;}
function restoreTaskContext(data){if(!data?.task_id)return null;const existing=state.taskContexts.get(data.task_id);if(existing)return existing;if(data.task_type!=='subtitle_transcription')return null;const pairId=String(data.subtitle_pair_id||'');const pair=state.pairs.find(item=>item.id===pairId);if(!pair)return null;if(data.status==='done'&&pair.has_source_srt&&!pair.needs_transcription)return null;const context={kind:'transcribe',pairId,videoPath:pair.video_path,foregroundOnly:Boolean(data.foreground_only)};state.taskContexts.set(data.task_id,context);return context;}
function updateTranscriptionTaskState(data,context){const pair=taskPair(context);if(!pair)return;if(data.status==='queued'||data.status==='running'||data.status==='interrupted'||data.status==='error'){pair.transcription_task_id=data.task_id;pair.transcription_status=data.status;pair.transcription_progress=data.progress||data.message||'';pair.transcription_error=data.status==='error'||data.status==='interrupted'?String(data.progress||data.error||''):'';}renderQueue();}
function reapplyKnownTaskStates(){for(const data of state.taskEvents.values()){const context=restoreTaskContext(data);if(context?.kind==='transcribe'&&data.status!=='done')updateTranscriptionTaskState(data,context);}}
async function startTranscription(){const pair=selectedPair();if(!pair||!pair.needs_transcription)return;const foregroundOnly=document.getElementById('foregroundOnly').checked;localStorage.setItem('autoslice.subtitle-foreground-only',foregroundOnly?'1':'0');const context={kind:'transcribe',pairId:pair.id,videoPath:pair.video_path,foregroundOnly};setBusy(true);setTask(foregroundOnly?'启动主要人声字幕识别...':'启动完整音轨字幕识别...');try{const data=await jsonRequest('/api/subtitles/transcribe',{method:'POST',body:JSON.stringify({video_path:pair.video_path,foreground_only:foregroundOnly})});registerTask(data.task_id,context);}catch(error){if(error.payload?.task_id){registerTask(error.payload.task_id,context);setTask('该视频已有字幕识别任务，正在接入进度...');}else{setBusy(false);setTask(error.message,'error');}}}
async function reflowSubtitles(){const pair=selectedPair();if(!pair||!pair.can_reflow_srt)return;setBusy(true);setTask(pair.is_reflowed_srt?'重新整理字幕...':'整理长字幕...');try{const result=await jsonRequest('/api/subtitles/reflow',{method:'POST',body:JSON.stringify({video_path:pair.video_path,srt_path:pair.raw_srt_path||pair.srt_path})});pair.raw_srt_path=result.source_srt_path;pair.srt_path=result.srt_path;pair.srt_name=String(result.srt_path||'').split(/[\\/]/).pop();pair.corrected_srt_path=result.corrected_srt_path;pair.has_corrected_srt=false;pair.is_reflowed_srt=true;pair.can_reflow_srt=true;pair.cue_count=Number(result.cue_count)||0;renderQueue();setBusy(false);await selectPair(state.selectedIndex);setTask(`已整理为 ${result.cue_count} 条字幕`,'done');}catch(error){setTask(error.message,'error');setBusy(false);}}
async function startReview(force=false){const pair=selectedPair();if(!pair)return;persistExtraGlossary(document.getElementById('extraGlossary')?.value||'');const context={kind:'review',pairId:pair.id,srtPath:pair.srt_path,extraGlossary:[...state.extraGlossary]};setBusy(true);setTask(force?'重新调用 AI 检查...':'启动 AI 检查...');try{const data=await jsonRequest('/api/subtitles/review',{method:'POST',body:JSON.stringify({video_path:pair.video_path,srt_path:pair.srt_path,context_title:pair.title,glossary:state.extraGlossary,force})});renderReviewDictionary(data.review_profile);registerTask(data.task_id,context);}catch(error){if(error.payload?.task_id){registerTask(error.payload.task_id,context);setTask('该字幕已有检查任务，正在接入进度...');}else{setBusy(false);setTask(error.message,'error');}}}
function applyReview(result,context){const pair=selectedPair();if(!pair||pair.id!==context.pairId)return false;if(result.source_srt_path&&normaliseWindowsPath(result.source_srt_path)!==normaliseWindowsPath(context.srtPath))throw new Error('AI 校对结果不属于当前字幕，已拒绝应用');renderReviewDictionary(result);for(const index of state.aiApplied){const previous=state.suggestions.get(index);if(!state.protectedEdits.has(index)&&previous&&state.edited.get(index)===previous.corrected)state.edited.set(index,sourceText(index));}state.aiApplied.clear();state.ignoredSuggestions.clear();state.suggestionUndoStack=[];const validSuggestions=[];for(const item of Array.isArray(result.suggestions)?result.suggestions:[]){const index=Number(item.index);if(state.deleted.has(index)||!Number.isInteger(index)||sourceText(index)!==item.original||typeof item.corrected!=='string'||!item.corrected.trim())continue;validSuggestions.push({...item,index});}state.suggestions=new Map(validSuggestions.map(item=>[item.index,item]));const defaults=new Set((Array.isArray(result.default_corrections)?result.default_corrections:[]).map(item=>Number(item.index)));for(const suggestion of state.suggestions.values()){const index=suggestion.index;if(defaults.has(index)&&!state.protectedEdits.has(index)&&state.edited.get(index)===sourceText(index)){state.edited.set(index,suggestion.corrected);state.aiApplied.add(index);}}renderCues();const cacheNote=result.cache_hit?'（使用有效缓存）':'';setTask(`发现 ${state.suggestions.size} 条校对建议${cacheNote}`,'done');setBusy(false);return true;}

function clearPreview(){if(state.previewUrl){URL.revokeObjectURL(state.previewUrl);state.previewUrl='';}const image=document.getElementById('previewImage');if(image){image.removeAttribute('src');image.style.display='none';}const placeholder=document.getElementById('previewPlaceholder');if(placeholder)placeholder.style.display='block';}
function updateArtifact(){document.getElementById('artifactPath').textContent=state.correctedPath||'尚未生成校对字幕';}

async function preview(){const pair=selectedPair();if(!pair)return;persistSubtitleSettings();setBusy(true);setTask('生成字幕预览（不保存校对字幕）...');try{const response=await fetch('/api/subtitles/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({video_path:pair.video_path,srt_path:pair.srt_path,corrections:corrections(),deleted_indices:deletions(),merge_pairs:mergePairs(),merge_overrides:mergeOverrides(),time_overrides:timeOverrides(),style:styleValues(),export:exportValues(),preview_time:Number(document.getElementById('previewTime').value)})});if(!response.ok){const data=await response.json();throw new Error(data.error||'预览失败');}const blob=await response.blob();if(state.previewUrl)URL.revokeObjectURL(state.previewUrl);state.previewUrl=URL.createObjectURL(blob);const image=document.getElementById('previewImage');image.src=state.previewUrl;image.style.display='block';document.getElementById('previewPlaceholder').style.display='none';setTask('预览已更新，未修改正式校对字幕','done');}catch(error){setTask(error.message,'error');}finally{setBusy(false);}}

async function renderVideo(){const pair=selectedPair();const srtPath=state.correctedPath||pair?.corrected_srt_path;if(!pair)return;if(!pair.has_corrected_srt||!srtPath){setTask('请先点击“保存校对字幕”，确认字幕落盘后再压制','error');return;}const context={kind:'render',pairId:pair.id,srtPath};setBusy(true);setTask('使用已保存字幕启动压制...');try{const data=await jsonRequest('/api/subtitles/render',{method:'POST',body:JSON.stringify({video_path:pair.video_path,srt_path:srtPath,style:styleValues(),export:exportValues()})});registerTask(data.task_id,context);}catch(error){setBusy(false);setTask(error.message,'error');}}

function rememberTaskEvent(data){state.taskEvents.set(data.task_id,data);while(state.taskEvents.size>100)state.taskEvents.delete(state.taskEvents.keys().next().value);}
function finishTask(taskId){state.taskContexts.delete(taskId);state.taskEvents.delete(taskId);setBusy(false);}
function connectSSE(){if(state.sseReconnectTimer){clearTimeout(state.sseReconnectTimer);state.sseReconnectTimer=null;}if(state.sse)state.sse.close();state.sse=new EventSource('/api/events');const handle=payload=>{for(const [taskId,data] of Object.entries(payload||{})){if(!taskId.startsWith('subtitle_'))continue;handleTask({task_id:taskId,...data});}};state.sse.addEventListener('init',event=>handle(JSON.parse(event.data)));state.sse.addEventListener('task_update',event=>handleTask(JSON.parse(event.data)));state.sse.onerror=()=>{if(state.sse){state.sse.close();state.sse=null;}if(!state.sseReconnectTimer)state.sseReconnectTimer=setTimeout(connectSSE,3000);};}
async function loadTaskResult(taskId){const response=await fetch(`/api/tasks/${encodeURIComponent(taskId)}/result`);if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.error||'任务结果读取失败');}return response.json();}
async function handleTask(data){if(!data.task_id?.startsWith('subtitle_'))return;rememberTaskEvent(data);const context=restoreTaskContext(data);if(!context)return;const pair=taskPair(context);if(!pair)return;if(context.kind==='transcribe')updateTranscriptionTaskState(data,context);const selected=selectedPair();if(data.status!=='done'&&data.status!=='error'&&data.status!=='interrupted'){if(selected?.id===context.pairId)setTask(data.progress||data.status);return;}if(data.status==='done'){try{const result=await loadTaskResult(data.task_id);if(context.kind==='transcribe'){if(normaliseWindowsPath(result.video_path)!==normaliseWindowsPath(context.videoPath))throw new Error('字幕识别结果不属于当前视频，已拒绝应用');pair.srt_path=result.srt_path;pair.srt_name=String(result.srt_path||'').split(/[\\/]/).pop();pair.has_source_srt=true;pair.needs_transcription=false;pair.subtitle_error='';pair.cue_count=Number(result.cue_count)||0;delete pair.transcription_task_id;delete pair.transcription_status;delete pair.transcription_progress;delete pair.transcription_error;renderQueue();finishTask(data.task_id);if(selected?.id===context.pairId)await selectPair(state.selectedIndex);else setTask(`字幕识别完成：${pair.title}`,'done');return;}if(selected?.id!==context.pairId)return;if(context.kind==='review')applyReview(result,context);if(context.kind==='title'){if(normaliseWindowsPath(result.source_srt_path)!==normaliseWindowsPath(context.srtPath))throw new Error('参考标题不属于当前字幕，已拒绝显示');state.referenceTitles=result;renderReferenceTitles();setTask('参考标题生成完成','done');}if(context.kind==='render'){pair.has_output_video=true;renderQueue();setTask(`压制完成：${result.output_video_path}`,'done');}finishTask(data.task_id);}catch(error){if(selected?.id===context.pairId)setTask(error.message,'error');if(context.kind==='transcribe'){pair.transcription_status='error';pair.transcription_error=error.message;renderQueue();}finishTask(data.task_id);}}else if(data.status==='error'||data.status==='interrupted'){if(selected?.id===context.pairId)setTask(data.progress||data.error||'字幕识别任务已中断','error');finishTask(data.task_id);}}

// 合并关系以“后一条 -> 前一条”保存，输出时才能准确延长时间轴而非伪装成删除。
function mergeRoot(index){let current=Number(index);const visited=new Set();while(state.mergePrevious.has(current)&&!visited.has(current)){visited.add(current);current=Number(state.mergePrevious.get(current));}return current;}
function mergeChildOf(index){const parent=Number(index);for(const [child,previous] of state.mergePrevious){if(Number(previous)===parent)return Number(child);}return null;}
function mergeMembers(index){const root=mergeRoot(index);const first=state.sourceCues.find(cue=>Number(cue.index)===root);if(!first)return[];const members=[first];const visited=new Set([root]);let current=root;while(true){const child=mergeChildOf(current);if(child===null||visited.has(child))break;const cue=state.sourceCues.find(item=>Number(item.index)===child);if(!cue)break;members.push(cue);visited.add(child);current=child;}return members;}
function isMergedChild(index){return state.mergePrevious.has(Number(index));}
function joinSubtitleText(left,right){const leftText=String(left||'').trim();const rightText=String(right||'').trim();if(!leftText)return rightText;if(!rightText)return leftText;if(/\s$/.test(String(left||''))||/^\s/.test(String(right||'')))return `${leftText} ${rightText}`;return leftText+rightText;}
function mergedDefaultText(index){return mergeMembers(index).reduce((text,cue)=>joinSubtitleText(text,state.edited.get(cue.index)??cue.text),'');}
function mergedDisplayText(index){const root=mergeRoot(index);return state.mergeOverrides.get(root)??mergedDefaultText(root);}
function mergeEndCue(index){const members=mergeMembers(index);return members[members.length-1]||null;}
function parseSrtTime(value){const match=String(value||'').trim().match(/^(?:(\d{1,3}):)?(\d{1,2}):(\d{2})(?:[,.](\d{1,3}))?$/);if(!match)return null;const hours=Number(match[1]||0),minutes=Number(match[2]),seconds=Number(match[3]),milliseconds=Number(String(match[4]||'0').padEnd(3,'0'));if(minutes>59||seconds>59||milliseconds>999)return null;return hours*3600+minutes*60+seconds+milliseconds/1000;}
function formatSrtTime(seconds){const total=Math.max(0,Math.round((Number(seconds)||0)*1000));const hours=Math.floor(total/3600000);const minutes=Math.floor(total%3600000/60000);const secs=Math.floor(total%60000/1000);const ms=total%1000;return `${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(secs).padStart(2,'0')},${String(ms).padStart(3,'0')}`;}
function defaultGroupTiming(index){const members=mergeMembers(index);const first=members[0];const last=members[members.length-1];return{start:Number(first?.start_seconds)||0,end:Number(last?.end_seconds)||0};}
function groupTiming(index){const root=mergeRoot(index);return state.timeOverrides.get(root)||defaultGroupTiming(root);}
function timeOverrides(){const result={};for(const [index,timing] of state.timeOverrides){const defaults=defaultGroupTiming(index);if(Math.abs(Number(timing.start)-defaults.start)>0.0005||Math.abs(Number(timing.end)-defaults.end)>0.0005)result[String(index)]={start:Number(timing.start),end:Number(timing.end)};}return result;}
function timingChanged(index){return Object.prototype.hasOwnProperty.call(timeOverrides(),String(mergeRoot(index)));}
function mergeCount(){return state.sourceCues.length?state.mergePrevious.size:0;}
function mergePairs(){return [...state.mergePrevious.entries()].sort((left,right)=>Number(left[0])-Number(right[0])).map(([second,first])=>({first:Number(first),second:Number(second)}));}
function mergeOverrides(){const result={};for(const [index,text] of state.mergeOverrides){const defaultText=mergedDefaultText(index);if(String(text).trim()&&String(text)!==defaultText)result[String(index)]=String(text);}return result;}
function cuePosition(index){return state.sourceCues.findIndex(cue=>Number(cue.index)===Number(index));}
function timingRoots(){return state.sourceCues.filter(cue=>mergeRoot(cue.index)===Number(cue.index)&&!state.deleted.has(Number(cue.index)));}
function validateTiming(index,start,end){if(!Number.isFinite(start)||!Number.isFinite(end))return'请输入有效的时间';if(start<0)return'开始时间不能小于 0';if(end<=start)return'结束时间必须晚于开始时间';const root=mergeRoot(index);if(root!==Number(index))return'合并字幕必须调整整组时间';const roots=timingRoots();const position=roots.findIndex(cue=>Number(cue.index)===root);if(position<0)return'当前字幕已删除，无法调整时间';const previous=position>0?groupTiming(roots[position-1].index):null;const next=position<roots.length-1?groupTiming(roots[position+1].index):null;if(previous&&start<Number(previous.start)-0.0005)return'开始时间不能早于上一条字幕';if(next&&start>Number(next.start)+0.0005)return'开始时间不能晚于下一条字幕的开始时间';return'';}
function shiftCueTiming(index,direction){const root=mergeRoot(index);const input=document.querySelector(`.cue-row[data-index="${root}"] [data-shift-seconds]`);const seconds=Number(input?.value);if(!Number.isFinite(seconds)||seconds<=0){setTask('请输入大于 0 的移动秒数','error');input?.focus();return;}const current=groupTiming(root);const delta=seconds*(direction<0?-1:1);const start=Number(current.start)+delta;const end=Number(current.end)+delta;const message=validateTiming(root,start,end);if(message){setTask(message,'error');return;}const defaults=defaultGroupTiming(root);if(Math.abs(start-defaults.start)<=0.0005&&Math.abs(end-defaults.end)<=0.0005)state.timeOverrides.delete(root);else state.timeOverrides.set(root,{start,end});state.selectedCueIndex=root;renderCues();}
function unmergeGroup(index,force=false){const root=mergeRoot(index);const members=mergeMembers(root);if(members.length<2)return false;const override=state.mergeOverrides.get(root);if(!force&&override!==undefined&&String(override)!==mergedDefaultText(root)){setTask('合并字幕正文已手工修改，请先恢复合并原文再拆开','error');return false;}const timing=state.timeOverrides.get(root);state.mergeOverrides.delete(root);state.timeOverrides.delete(root);for(const cue of members.slice(1))state.mergePrevious.delete(Number(cue.index));if(timing){const first=members[0],last=members[members.length-1];if(Math.abs(Number(timing.start)-Number(first.start_seconds))>0.0005)state.timeOverrides.set(Number(first.index),{start:Number(timing.start),end:Number(first.end_seconds)});if(Math.abs(Number(timing.end)-Number(last.end_seconds))>0.0005)state.timeOverrides.set(Number(last.index),{start:Number(last.start_seconds),end:Number(timing.end)});}return true;}
function mergeGroups(leftIndex,rightIndex){const leftRoot=mergeRoot(leftIndex);const rightRoot=mergeRoot(rightIndex);if(leftRoot===rightRoot)return false;const leftMembers=mergeMembers(leftRoot);const rightMembers=mergeMembers(rightRoot);const leftTail=leftMembers[leftMembers.length-1];const rightFirst=rightMembers[0];if(!leftTail||!rightFirst||cuePosition(rightFirst.index)!==cuePosition(leftTail.index)+1)return false;if(state.deleted.has(leftTail.index)||state.deleted.has(rightFirst.index))return false;const mustPreserveText=state.mergeOverrides.has(leftRoot)||state.mergeOverrides.has(rightRoot);const mustPreserveTiming=state.timeOverrides.has(leftRoot)||state.timeOverrides.has(rightRoot);const combinedText=joinSubtitleText(mergedDisplayText(leftRoot),mergedDisplayText(rightRoot));const combinedTiming={start:groupTiming(leftRoot).start,end:groupTiming(rightRoot).end};state.mergePrevious.set(Number(rightFirst.index),Number(leftTail.index));state.mergeOverrides.delete(rightRoot);state.timeOverrides.delete(rightRoot);if(mustPreserveText)state.mergeOverrides.set(leftRoot,combinedText);if(mustPreserveTiming)state.timeOverrides.set(leftRoot,combinedTiming);return true;}
function mergeWithPrevious(index){const root=mergeRoot(index);const position=cuePosition(root);if(position<=0){setTask('当前已是第一条字幕，无法向上合并','error');return;}const previous=state.sourceCues[position-1];if(state.deleted.has(previous.index)){setTask('上一条字幕已删除，无法合并','error');return;}if(mergeGroups(previous.index,root))renderCues();}
function mergeWithNext(index){const root=mergeRoot(index);const tail=mergeEndCue(root);const position=tail?cuePosition(tail.index):-1;if(position<0||position>=state.sourceCues.length-1){setTask('当前已是最后一条字幕，无法向下合并','error');return;}const next=state.sourceCues[position+1];if(state.deleted.has(next.index)){setTask('下一条字幕已删除，无法合并','error');return;}if(mergeGroups(root,next.index))renderCues();}
function restoreCorrectedState(sourceCues,correctedCues){if(!Array.isArray(correctedCues)||!correctedCues.length||correctedCues.length>sourceCues.length)return false;let sourceCursor=0;for(const correctedCue of correctedCues){let startPosition=-1;for(let position=sourceCursor;position<sourceCues.length;position+=1){const sourceCue=sourceCues[position];if(Number(sourceCue.index)===Number(correctedCue.index)&&sourceCue.start===correctedCue.start&&String(sourceCue.settings||'')===String(correctedCue.settings||'')){startPosition=position;break;}}if(startPosition<0)return false;for(let position=sourceCursor;position<startPosition;position+=1)state.deleted.add(Number(sourceCues[position].index));let endPosition=startPosition;while(endPosition<sourceCues.length&&sourceCues[endPosition].end!==correctedCue.end)endPosition+=1;if(endPosition>=sourceCues.length)return false;const members=sourceCues.slice(startPosition,endPosition+1);const root=Number(members[0].index);if(members.length>1){for(let position=1;position<members.length;position+=1)state.mergePrevious.set(Number(members[position].index),Number(members[position-1].index));state.mergeOverrides.set(root,correctedCue.text);state.protectedEdits.add(root);}else{state.edited.set(root,correctedCue.text);if(correctedCue.text!==sourceText(root))state.protectedEdits.add(root);}sourceCursor=endPosition+1;}for(let position=sourceCursor;position<sourceCues.length;position+=1)state.deleted.add(Number(sourceCues[position].index));return true;}
function applySavedEditState(saved){if(!saved||typeof saved!=='object')return false;for(const item of saved.corrections||[]){const index=Number(item.index);if(!Number.isInteger(index)||sourceText(index)!==item.original||!String(item.corrected??'').trim())return false;state.edited.set(index,item.corrected);state.protectedEdits.add(index);}for(const rawIndex of saved.deleted_indices||[]){const index=Number(rawIndex);if(!Number.isInteger(index)||!state.sourceCues.some(cue=>Number(cue.index)===index))return false;state.deleted.add(index);state.deletedSnapshots.set(index,{members:[index],mergePrevious:[],mergeOverride:undefined,timeOverride:undefined});}for(const pair of saved.merge_pairs||[]){const first=Number(pair.first),second=Number(pair.second);if(!Number.isInteger(first)||!Number.isInteger(second)||first===second||state.deleted.has(first)||state.deleted.has(second))return false;state.mergePrevious.set(second,first);}for(const [index,text] of Object.entries(saved.merge_overrides||{}))state.mergeOverrides.set(Number(index),String(text));for(const [index,timing] of Object.entries(saved.time_overrides||{})){const start=Number(timing?.start),end=Number(timing?.end);if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start||state.deleted.has(Number(index))||state.mergePrevious.has(Number(index)))return false;state.timeOverrides.set(Number(index),{start,end});}return true;}

async function selectPair(index){if(state.busy)return;cancelScheduledQualityRender();clearPreview();const selection=++state.selectionVersion;state.selectedIndex=index;state.suggestions.clear();state.ignoredSuggestions.clear();state.suggestionUndoStack=[];state.aiApplied.clear();state.protectedEdits.clear();state.deleted.clear();state.deletedSnapshots.clear();state.deleteSelection.clear();state.mergePrevious.clear();state.mergeOverrides.clear();state.timeOverrides.clear();state.selectedCueIndex=null;state.qualityIgnored.clear();state.qualityActions=[];state.qualityActionSerial=0;state.correctedPath='';const pair=selectedPair();loadExtraGlossary(pair);renderReviewDictionary();renderQueue();renderQualityList();if(!pair)return;const pairId=pair.id;document.getElementById('editorTitle').textContent=pair.title;document.getElementById('editorTitle').title=pair.title;if(pair.needs_transcription){document.getElementById('editorPath').textContent=pair.video_path;document.getElementById('editorPath').title=pair.video_path;document.getElementById('cueList').innerHTML='<div class="queue-empty">该成片尚无字幕</div>';document.getElementById('artifactPath').textContent=`将生成：${pair.srt_path}`;renderSuggestionTools();renderQualityList();setTask('等待自动识别字幕');updateChangeCount();updateActionState();return;}document.getElementById('editorPath').textContent=pair.srt_path;document.getElementById('editorPath').title=pair.srt_path;if(pair.subtitle_error){document.getElementById('cueList').innerHTML='<div class="queue-empty">字幕文件无法读取</div>';renderSuggestionTools();renderQualityList();setTask(pair.subtitle_error,'error');updateActionState();return;}setBusy(true);setTask('加载字幕...');try{const source=await jsonRequest('/api/subtitles/cues',{method:'POST',body:JSON.stringify({srt_path:pair.srt_path})});if(selection!==state.selectionVersion||selectedPair()?.id!==pairId)return;state.sourceCues=source.cues||[];state.edited=new Map(state.sourceCues.map(cue=>[cue.index,cue.text]));if(pair.has_corrected_srt){const savedResponse=await jsonRequest('/api/subtitles/edit-state',{method:'POST',body:JSON.stringify({srt_path:pair.srt_path})});if(selection!==state.selectionVersion||selectedPair()?.id!==pairId)return;if(savedResponse.available){if(!applySavedEditState(savedResponse.edit_state))throw new Error('已有字幕校对状态无效，请重新保存校对字幕');}else{const corrected=await jsonRequest('/api/subtitles/cues',{method:'POST',body:JSON.stringify({srt_path:pair.corrected_srt_path})});if(selection!==state.selectionVersion||selectedPair()?.id!==pairId)return;if(!restoreCorrectedState(state.sourceCues,corrected.cues||[]))throw new Error('已有校对字幕与当前源字幕时间轴不一致，请重新保存校对字幕');}state.correctedPath=pair.corrected_srt_path;}const maxTime=state.sourceCues.reduce((max,cue)=>Math.max(max,Number(cue.end_seconds)||0),1);const first=state.sourceCues[0];const preview=first?(Number(first.start_seconds)+Number(first.end_seconds))/2:0;document.getElementById('previewRange').max=maxTime.toFixed(1);document.getElementById('previewRange').value=preview.toFixed(1);document.getElementById('previewTime').value=preview.toFixed(1);renderCues();updateArtifact();setTask(`字幕已加载，共 ${state.sourceCues.length} 条`,'done');}catch(error){if(selection===state.selectionVersion)setTask(error.message,'error');}finally{if(selection===state.selectionVersion)setBusy(false);}}

const clearEditorWithoutTitleReset=clearEditor;
clearEditor=function(){state.referenceTitles=null;renderReferenceTitles();return clearEditorWithoutTitleReset();};
const selectPairWithoutTitleReset=selectPair;
selectPair=async function(index){state.referenceTitles=null;renderReferenceTitles();renderReviewDictionary();return selectPairWithoutTitleReset(index);};

async function generateReferenceTitle(){const pair=selectedPair();if(!pair)return;if(!pair.has_corrected_srt||!state.correctedPath){setTask('请先点击“保存校对字幕”，再生成参考标题','error');return;}setBusy(true);state.referenceTitles=null;renderReferenceTitles();setTask('读取已保存字幕并准备标题材料...');try{const srtPath=state.correctedPath;const context={kind:'title',pairId:pair.id,srtPath};const data=await jsonRequest('/api/subtitles/generate-title',{method:'POST',body:JSON.stringify({video_path:pair.video_path,srt_path:srtPath,context_title:pair.title})});registerTask(data.task_id,context);document.getElementById('generateTitleButton').textContent='重新生成标题';}catch(error){if(error.payload?.task_id){registerTask(error.payload.task_id,{kind:'title',pairId:pair.id,srtPath:state.correctedPath||pair.corrected_srt_path});setTask('该字幕已有标题任务，正在接入进度...');}else{setBusy(false);setTask(error.message,'error');}}}
async function copyRecommendedTitle(){const title=state.referenceTitles?.recommended_title;if(!title)return;try{await navigator.clipboard.writeText(title);setTask('推荐标题已复制','done');}catch(error){setTask('浏览器无法复制，请手动选中标题','error');}}

function cueChanged(cue){const root=mergeRoot(cue.index);if(root!==Number(cue.index))return false;if(mergeMembers(root).length>1||timingChanged(root))return true;return(state.edited.get(cue.index)??cue.text)!==cue.text;}
function suggestionFor(index){const numeric=Number(index);return state.ignoredSuggestions.has(numeric)?null:state.suggestions.get(numeric)||null;}
function visibleCue(cue){const root=mergeRoot(cue.index);if(root!==Number(cue.index))return false;const deleted=state.deleted.has(cue.index);if(state.filter==='suggested')return !deleted&&Boolean(suggestionFor(cue.index));if(state.filter==='changed')return deleted||cueChanged(cue);return !deleted;}
function visibleSuggestionEntries(){return state.sourceCues.filter(cue=>{if(mergeRoot(cue.index)!==Number(cue.index)||state.deleted.has(cue.index)||!suggestionFor(cue.index))return false;if(state.filter==='suggested')return true;if(state.filter==='changed')return cueChanged(cue);return true;}).map(cue=>({cue,suggestion:suggestionFor(cue.index)}));}
function isProtectedSuggestion(index){const numeric=Number(index);return state.protectedEdits.has(numeric)||(state.edited.has(numeric)&&state.edited.get(numeric)!==sourceText(numeric)&&!state.aiApplied.has(numeric));}
function singleCharacterReplacement(suggestion){if(suggestion?.source==='fixed_replacement')return false;const original=String(suggestion?.original||'').replace(/\s+/g,'');const corrected=String(suggestion?.corrected||'').replace(/\s+/g,'');if(!original||original.length!==corrected.length)return false;let differences=0;for(let index=0;index<original.length;index+=1)if(original[index]!==corrected[index])differences+=1;return differences===1;}
function suggestionReplacementCandidate(suggestion){const original=String(suggestion?.original||'');const corrected=String(suggestion?.corrected||'');let start=0;while(start<original.length&&start<corrected.length&&original[start]===corrected[start])start+=1;let end=0;while(end<original.length-start&&end<corrected.length-start&&original[original.length-1-end]===corrected[corrected.length-1-end])end+=1;const source=original.slice(start,original.length-end).trim();const target=corrected.slice(start,corrected.length-end).trim();if(!source||!target||source===target||start+end<2||source.length>24||target.length>24||/[\n\r]/.test(source+target))return null;return{source,target};}
function suggestionGroups(entries){const groups=new Map();for(const entry of entries){const key=JSON.stringify([entry.suggestion.original,entry.suggestion.corrected]);const group=groups.get(key)||{original:entry.suggestion.original,corrected:entry.suggestion.corrected,items:[]};group.items.push(entry);groups.set(key,group);}return [...groups.values()];}
function renderSuggestionReplacementActions(candidate){if(!candidate||state.reviewProfile?.profile_write_available!==true)return'';const key=JSON.stringify([candidate.source,candidate.target]);if(state.profileKnownPairs?.has(key)&&!state.profileAddedPairs?.has(key))return'<span class="suggestion-profile-known">已在主播词库</span>';const added=state.profileAddedPairs?.has(key);const action=added?'remove-profile-replacement':'add-profile-replacement';const label=added?'撤销本机词库':'加入主播词库';return `<button class="suggestion-profile-action" type="button" data-action="${action}" data-source="${esc(candidate.source)}" data-target="${esc(candidate.target)}">${label}</button>`;}
function renderSuggestionTools(){const summary=document.getElementById('suggestionSummary');if(!summary)return;const entries=visibleSuggestionEntries();const groups=suggestionGroups(entries);const protectedCount=entries.filter(entry=>isProtectedSuggestion(entry.cue.index)).length;if(!entries.length){summary.innerHTML='<span class="suggestion-empty">当前筛选没有待处理的 AI 建议</span>';updateActionState();return;}summary.innerHTML=groups.map(group=>{const confidences=group.items.map(item=>Number(item.suggestion.confidence)).filter(Number.isFinite);const average=confidences.length?Math.round(confidences.reduce((sum,value)=>sum+value,0)/confidences.length*100):0;const indices=group.items.map(item=>item.cue.index).join('、');const reason=[...new Set(group.items.map(item=>String(item.suggestion.reason||'').trim()).filter(Boolean))][0]||'未提供原因';const context=group.items.slice(0,5).map(item=>`第 ${item.cue.index} 条：${item.cue.text}`).join('；');const candidate=suggestionReplacementCandidate(group.items[0].suggestion);return `<div class="suggestion-group"><div class="suggestion-group-main"><strong>${group.items.length} 条</strong><span>${esc(group.original)} → ${esc(group.corrected)}</span></div><div class="suggestion-group-meta">第 ${esc(indices)} 条 · 置信度 ${average}% · ${esc(reason)}</div><div class="suggestion-group-context">${esc(context)}${group.items.length>5?'；其余命中见对应字幕':''}</div>${renderSuggestionReplacementActions(candidate)}</div>`;}).join('')+(protectedCount?`<div class="suggestion-protected">${protectedCount} 条已保留手工修改，批量采纳不会覆盖</div>`:'');summary.querySelectorAll('[data-action="add-profile-replacement"],[data-action="remove-profile-replacement"]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.action;const source=button.dataset.source;const target=button.dataset.target;if(action==='add-profile-replacement')saveProfileReplacement(source,target);else removeProfileReplacement(source,target);}));updateActionState();}
async function saveProfileReplacement(source,target){const profile=state.reviewProfile;if(!profile?.profile_write_available){setTask('当前主播没有可写入的具体 profile，请先配置主播', 'error');return;}if(!confirm(`确认将“${source} → ${target}”加入 ${profile.label} 的主播词库？以后该主播的字幕识别热词、错词校正和 AI 校对都会受到影响，已有缓存会按新规则失效。`))return;setBusy(true);try{const result=await jsonRequest('/api/subtitles/profile-replacements',{method:'POST',body:JSON.stringify({streamer_profile_id:profile.id,source,target,profile_fingerprint:profile.profile_fingerprint,confirm_scope:true})});if(result.added)state.profileAddedPairs.add(JSON.stringify([source,target]));state.reviewProfile={...profile,replacements:[...(Array.isArray(profile.replacements)?profile.replacements:[]),...(result.added?[[source,target]]:[])],replacement_count:Number(result.replacement_count)||profile.replacement_count,profile_fingerprint:result.profile_fingerprint};renderReviewDictionary(state.reviewProfile);renderSuggestionTools();setTask(result.added?`已加入 ${profile.label} 主播词库，请重新 AI 检查以应用`:'该映射已存在于主播词库','done');}catch(error){setTask(error.message,'error');}finally{setBusy(false);}}
async function removeProfileReplacement(source,target){const profile=state.reviewProfile;if(!profile?.profile_write_available)return;if(!confirm(`确认撤销本机词库中的“${source} → ${target}”吗？`))return;setBusy(true);try{const result=await jsonRequest('/api/subtitles/profile-replacements',{method:'DELETE',body:JSON.stringify({streamer_profile_id:profile.id,source,target,profile_fingerprint:profile.profile_fingerprint,confirm_scope:true})});state.profileAddedPairs.delete(JSON.stringify([source,target]));state.reviewProfile={...profile,replacements:(Array.isArray(profile.replacements)?profile.replacements:[]).filter(item=>!(Array.isArray(item)&&item[0]===source&&item[1]===target)),replacement_count:Number(result.replacement_count)||0,profile_fingerprint:result.profile_fingerprint};renderReviewDictionary(state.reviewProfile);renderSuggestionTools();setTask('已撤销本机主播词库映射，请重新 AI 检查以应用','done');}catch(error){setTask(error.message,'error');}finally{setBusy(false);}}
function suggestionUndoSnapshot(index){return{index:Number(index),hadText:state.edited.has(Number(index)),text:state.edited.get(Number(index)),wasAiApplied:state.aiApplied.has(Number(index)),wasIgnored:state.ignoredSuggestions.has(Number(index)),appliedText:state.edited.get(Number(index))};}
function restoreSuggestionSnapshot(snapshot){const index=Number(snapshot.index);if(state.protectedEdits.has(index)&&state.edited.get(index)!==snapshot.appliedText)return; if(snapshot.hadText)state.edited.set(index,snapshot.text);else state.edited.delete(index);if(snapshot.wasAiApplied)state.aiApplied.add(index);else state.aiApplied.delete(index);if(snapshot.wasIgnored)state.ignoredSuggestions.add(index);else state.ignoredSuggestions.delete(index);}
function confirmHighRiskSuggestions(entries){const risky=entries.filter(entry=>singleCharacterReplacement(entry.suggestion)&&!isProtectedSuggestion(entry.cue.index));if(!risky.length)return true;return window.confirm(`当前筛选包含 ${risky.length} 条高风险单字替换建议，是否继续批量采纳？`);}
function recordSuggestionUndo(changes,label){if(!changes.length)return;state.suggestionUndoStack.push({label,changes});while(state.suggestionUndoStack.length>20)state.suggestionUndoStack.shift();}
function acceptVisibleSuggestions(){const entries=visibleSuggestionEntries();if(!entries.length){setTask('当前筛选没有待采纳的 AI 建议','error');return;}if(!confirmHighRiskSuggestions(entries))return;const changes=[];let skipped=0;for(const entry of entries){const index=Number(entry.cue.index);const snapshot=suggestionUndoSnapshot(index);if(isProtectedSuggestion(index)){skipped+=1;continue;}state.edited.set(index,entry.suggestion.corrected);state.aiApplied.add(index);state.ignoredSuggestions.delete(index);snapshot.appliedText=entry.suggestion.corrected;changes.push(snapshot);}recordSuggestionUndo(changes,'采纳建议');renderCues();setTask(`已采纳 ${changes.length} 条建议${skipped?`，保留 ${skipped} 条手工修改`:''}`,'done');}
function ignoreVisibleSuggestions(){const entries=visibleSuggestionEntries();if(!entries.length){setTask('当前筛选没有待忽略的 AI 建议','error');return;}const changes=[];let protectedCount=0;for(const entry of entries){const index=Number(entry.cue.index);const snapshot=suggestionUndoSnapshot(index);if(isProtectedSuggestion(index))protectedCount+=1;state.ignoredSuggestions.add(index);if(!isProtectedSuggestion(index)&&state.aiApplied.has(index)&&state.edited.get(index)===entry.suggestion.corrected){state.edited.set(index,sourceText(index));state.aiApplied.delete(index);}snapshot.appliedText=state.edited.get(index);changes.push(snapshot);}recordSuggestionUndo(changes,'忽略建议');renderCues();setTask(`已忽略 ${changes.length} 条建议${protectedCount?`，保留 ${protectedCount} 条手工修改`:''}`,'done');}
function undoSuggestionAction(){const operation=state.suggestionUndoStack.pop();if(!operation){setTask('没有可撤销的批量建议操作','error');return;}for(const snapshot of operation.changes)restoreSuggestionSnapshot(snapshot);renderCues();setTask(`已撤销：${operation.label}`,'done');}

const QUALITY_TYPE_LABELS={'background-noise':'疑似背景音乱码','exact-duplicate':'完全重复','symbol-or-short':'纯符号或异常短句','low-confidence-semantic':'低置信度且语义异常','deletion-blank':'删除后大段空白','abnormal-gap':'相邻字幕异常 gap','overflow-risk':'超长文本 / 屏幕溢出','segmentation-residue':'分段残留 / 连接词错位'};
const QUALITY_TYPE_ORDER=Object.keys(QUALITY_TYPE_LABELS);
const QUALITY_CONNECTORS=new Set(['所以','但是','然后','不过','而且','因为','可是','就是','那么','如果','其实']);
const QUALITY_RENDER_DELAY_MS=140;
function cancelScheduledQualityRender(){if(state.qualityRenderTimer!==null){clearTimeout(state.qualityRenderTimer);state.qualityRenderTimer=null;}}
function scheduleQualityRender(){cancelScheduledQualityRender();const selection=state.selectionVersion;const timerId=setTimeout(()=>{if(state.qualityRenderTimer!==timerId)return;state.qualityRenderTimer=null;if(selection===state.selectionVersion)renderQualityList();},QUALITY_RENDER_DELAY_MS);state.qualityRenderTimer=timerId;}
function qualityText(index){return String(mergedDisplayText(index)??'').replace(/\s+/g,' ').trim();}
function qualityCompactText(value){return String(value??'').replace(/\s+/g,'');}
function qualityGroupTiming(index){const root=mergeRoot(index);if(state.deleted.has(root)){const cue=state.sourceCues.find(item=>Number(item.index)===root);return{start:Number(cue?.start_seconds)||0,end:Number(cue?.end_seconds)||0};}return groupTiming(root);}
function qualityGroups(){return state.sourceCues.filter(cue=>mergeRoot(cue.index)===Number(cue.index)&&!state.deleted.has(Number(cue.index))).map(cue=>{const members=mergeMembers(cue.index);const timing=qualityGroupTiming(cue.index);return{root:Number(cue.index),indices:members.map(item=>Number(item.index)),startPosition:cuePosition(cue.index),endPosition:cuePosition(members[members.length-1]?.index??cue.index),text:qualityText(cue.index),start:Number(timing.start),end:Number(timing.end)};});}
function qualityHash(value){let hash=2166136261;for(const character of String(value??'')){hash^=character.codePointAt(0);hash=Math.imul(hash,16777619);}return(hash>>>0).toString(36);}
function qualityContext(indices){const positions=indices.map(cuePosition).filter(position=>position>=0);if(!positions.length)return'';const start=Math.max(0,Math.min(...positions)-1),end=Math.min(state.sourceCues.length-1,Math.max(...positions)+1);const roots=[];for(let position=start;position<=end;position+=1){const cue=state.sourceCues[position];const root=mergeRoot(cue.index);if(!roots.includes(root))roots.push(root);}return roots.map(root=>`${state.deleted.has(root)?'已删 ':''}第 ${root} 条：${qualityText(root)||'（空正文）'}`).join('\n');}
function qualityIssue(type,indices,reason,recommendation,action=null,signature=''){const numeric=[...new Set(indices.map(Number))].sort((left,right)=>cuePosition(left)-cuePosition(right));const timings=numeric.map(qualityGroupTiming);const start=Math.min(...timings.map(item=>Number(item.start)||0));const end=Math.max(...timings.map(item=>Number(item.end)||0));const evidence=`${numeric.map(index=>qualityText(index)).join('|')}|${start.toFixed(3)}|${end.toFixed(3)}|${signature}`;return{id:`${type}:${numeric.join('-')}:${qualityHash(evidence)}`,type,label:QUALITY_TYPE_LABELS[type],indices:numeric,primaryIndex:numeric[0],start,end,reason,recommendation,context:qualityContext(numeric),action};}
function qualityLooksLikeBackgroundNoise(text){const compact=qualityCompactText(text);if(!compact)return false;if(/[\uFFFD]|锟斤拷|烫烫烫/i.test(compact))return true;if(/^[\[【（(]?(?:bgm|music|音乐|音效|歌词|笑声|掌声)[\]】）)]?$/i.test(compact))return true;if(/^[啊呀哈啦哦呜嗯哼嘿]{4,}$/.test(compact))return true;return compact.length>=6&&/^(.{1,2})\1{2,}$/.test(compact);}
function qualityIsPureSymbols(text){const compact=qualityCompactText(text);return Boolean(compact)&&!/[0-9A-Za-z\u3400-\u9fff]/.test(compact);}
function qualitySemanticAnomaly(text,suggestion){const compact=qualityCompactText(text);const reason=String(suggestion?.reason||'');if(qualityLooksLikeBackgroundNoise(text)||qualityIsPureSymbols(text)||compact.length<=2)return true;if(/语义|不通|异常|乱码|无法确认|疑似误识别|上下文不足/.test(reason))return true;const corrected=qualityCompactText(suggestion?.corrected);return Boolean(corrected)&&Math.abs(corrected.length-compact.length)>=Math.max(4,Math.ceil(compact.length*.6));}
function qualityDisplayCharLimit(){const fontValue=Number(document.getElementById('fontSize')?.value);const outlineValue=Number(document.getElementById('outlineWidth')?.value);const fontSize=(Number.isFinite(fontValue)&&fontValue>0?fontValue:20)*6.75;const outline=(Number.isFinite(outlineValue)&&outlineValue>=0?outlineValue:100)*.0533333333;const usableWidth=1920-2*Math.max(10,Math.round(1920*.04));return Math.max(6,Math.min(32,Math.floor(usableWidth/Math.max(1,fontSize*.92+outline*2))));}
function qualityDeletedBetween(left,right){return state.sourceCues.slice(left.endPosition+1,right.startPosition).filter(cue=>state.deleted.has(Number(cue.index))).map(cue=>Number(cue.index));}
function qualityIssues(){
    const issues=[];
    const groups=qualityGroups();
    const add=(...args)=>issues.push(qualityIssue(...args));
    for(let position=0;position<groups.length;position+=1){
        const group=groups[position];
        const compact=qualityCompactText(group.text);
        const previous=position>0?groups[position-1]:null;
        const next=position<groups.length-1?groups[position+1]:null;
        if(qualityLooksLikeBackgroundNoise(group.text))add('background-noise',group.indices,'正文符合背景音标签、乱码字符或机械重复音节特征。','先定位试听；确认不是有效人声后，仅加入删除预览。',{kind:'preview-delete',index:group.root,label:'加入删除预览'},'background');
        const duplicateGap=previous?group.start-previous.end:Infinity;
        if(previous&&compact&&compact===qualityCompactText(previous.text)&&duplicateGap>=-1.5&&duplicateGap<=1.5)add('exact-duplicate',[previous.root,group.root],'相邻两条当前可见正文完全一致，且 gap 在 -1.5～1.5 秒之间（重叠不超过 1.5 秒）。','保留前条，先把后条加入删除预览，确认画面和语气后再删除。',{kind:'preview-delete',index:group.root,label:'后条加入删除预览'},`duplicate:${duplicateGap}`);
        if(qualityIsPureSymbols(group.text))add('symbol-or-short',group.indices,'正文不包含中文、英文或数字，只剩符号。','先定位试听；确认无有效口播后，仅加入删除预览。',{kind:'preview-delete',index:group.root,label:'加入删除预览'},'symbols');
        else if(compact.length===1)add('symbol-or-short',group.indices,'当前字幕只有 1 个可见字符，可能是有效语气词，也可能是异常短句。','风险较高，只定位并展开检查，不自动改写。',null,'single');
        const suggestion=group.indices.length===1?state.suggestions.get(group.root):null;
        const confidence=Number(suggestion?.confidence);
        if(suggestion&&Number.isFinite(confidence)&&confidence<.8&&qualitySemanticAnomaly(group.text,suggestion))add('low-confidence-semantic',group.indices,`已有 AI 校对建议置信度 ${Math.round(confidence*100)}%，且正文或建议原因包含语义异常证据；这不是 ASR 置信度。`,'只定位对照上下文与 AI 建议，不自动采纳或删除。',null,`${confidence}|${suggestion.reason}|${suggestion.corrected}`);
        const limit=qualityDisplayCharLimit();
        if(compact.length>limit)add('overflow-risk',group.indices,`当前正文 ${compact.length} 个可见字符，超过按 1920×1080、当前字号和描边估算的单行安全值 ${limit}。`,'定位后手工精简、拆分或调整样式；保存契约保持不变。',null,`${compact.length}|${limit}`);
        const previousGap=previous?group.start-previous.end:Infinity;
        const nextGap=next?next.start-group.end:Infinity;
        if(QUALITY_CONNECTORS.has(compact)&&next&&nextGap>=-.05&&nextGap<=.8)add('segmentation-residue',[group.root,next.root],`连接词“${compact}”单独成条，且与下一条仅间隔 ${Math.max(0,nextGap).toFixed(2)} 秒。`,'可保守地与下一条合并；操作只改当前编辑态并可撤销。',{kind:'merge',left:group.root,right:next.root,label:'与下一条合并'},`connector-next:${compact}`);
        if(compact.length===1&&(previousGap<=.8||nextGap<=.8))add('segmentation-residue',group.indices,'单字与相邻字幕距离很近，可能是分段后残留的尾字或开头字。','只定位检查归属；无法可靠判断时不自动搬字。',null,`single-neighbour:${previousGap}:${nextGap}`);
        if(/^[\u3400-\u9fff]\s+\S/.test(group.text)&&previous&&previousGap<=.8)add('segmentation-residue',[previous.root,group.root],'当前条以“单字 + 空格”开头，且紧邻前条，可能是前条尾字漂移。','只定位检查；不要机械移动单字。',null,'leading-drift');
        if(previous&&QUALITY_CONNECTORS.has(qualityCompactText(previous.text).slice(-2))&&previousGap<=.8)add('segmentation-residue',[previous.root,group.root],'前条末尾停在连接词上，后条紧接正文，可能存在连接词错位。','只定位检查语义边界，必要时手工重排。',null,'trailing-connector');
    }
    for(let position=1;position<groups.length;position+=1){
        const previous=groups[position-1],current=groups[position];
        const gap=current.start-previous.end;
        const deleted=qualityDeletedBetween(previous,current);
        if(deleted.length&&gap>=5)add('deletion-blank',deleted,`删除这些字幕后，前后保留字幕之间形成 ${gap.toFixed(2)} 秒空白。`,'定位已删字幕并试听；需要时使用现有恢复入口，不自动恢复或保存。',null,`${previous.root}|${current.root}|${gap}`);
        else if(!deleted.length&&gap>=3)add('abnormal-gap',[previous.root,current.root],`相邻保留字幕之间存在 ${gap.toFixed(2)} 秒 gap，超过 3 秒检查阈值。`,'定位检查是否漏字或时间调整过大；不自动拉伸时间。',null,`${gap}`);
    }
    return issues.sort((left,right)=>cuePosition(left.primaryIndex)-cuePosition(right.primaryIndex)||QUALITY_TYPE_ORDER.indexOf(left.type)-QUALITY_TYPE_ORDER.indexOf(right.type));
}
function visibleQualityIssues(){return qualityIssues().filter(issue=>!state.qualityIgnored.has(issue.id));}
function qualityActionIsStale(action){if(action.kind==='preview-delete')return !state.deleted.has(action.root)&&!state.deleteSelection.has(action.root);if(action.kind==='merge')return state.mergePrevious.get(action.bridgeSecond)!==action.bridgeFirst;return false;}
function pruneStaleQualityActions(){state.qualityActions=state.qualityActions.filter(action=>!qualityActionIsStale(action));}
function qualityActionForIssue(issueId){pruneStaleQualityActions();return state.qualityActions.find(action=>action.issueId===issueId)||null;}
function qualityLocationText(issue){const indices=issue.indices.length>4?`${issue.indices.slice(0,4).join('、')} 等 ${issue.indices.length} 条`:issue.indices.join('、');return `第 ${indices} 条 · ${formatSrtTime(issue.start)} → ${formatSrtTime(issue.end)}`;}
function renderQualityActionReceipt(action){return `<article class="quality-card quality-action-receipt"><div class="quality-card-main"><div class="quality-card-title"><strong>已执行建议</strong><span>${esc(action.label)}</span></div><div class="quality-card-location">${esc(action.location)}</div><div class="quality-action-status">${esc(action.kind==='preview-delete'?'只加入删除预览，尚未删除或保存字幕。':'只合并当前编辑态，尚未保存字幕。')}</div></div><div class="quality-card-actions"><button class="button quiet" type="button" data-quality-undo="${action.id}">撤销建议动作</button></div></article>`;}
function renderQualityIssue(issue){const action=qualityActionForIssue(issue.id);const suggested=action?`<button class="button quiet" type="button" data-quality-undo="${action.id}">撤销建议动作</button>`:issue.action?`<button class="button" type="button" data-quality-action="${esc(issue.id)}">${esc(issue.action.label)}</button>`:'';return `<article class="quality-card" data-quality-issue="${esc(issue.id)}"><div class="quality-card-main"><div class="quality-card-title"><strong>${esc(issue.label)}</strong><span>${esc(issue.reason)}</span></div><div class="quality-card-location">${esc(qualityLocationText(issue))}</div><div class="quality-card-context">${esc(issue.context)}</div><div class="quality-card-recommendation">建议：${esc(issue.recommendation)}</div></div><div class="quality-card-actions"><button class="button quiet" type="button" data-quality-locate="${esc(issue.id)}">定位检查</button>${suggested}<button class="button quiet" type="button" data-quality-ignore="${esc(issue.id)}">忽略</button></div></article>`;}
function renderQualityList(){cancelScheduledQualityRender();pruneStaleQualityActions();const count=document.getElementById('qualityCount'),summary=document.getElementById('qualitySummary'),list=document.getElementById('qualityList'),reset=document.getElementById('qualityResetIgnored');if(!count||!summary||!list)return;const all=qualityIssues();const visible=all.filter(issue=>!state.qualityIgnored.has(issue.id));const ignoredCount=all.length-visible.length;count.textContent=`${visible.length} 条${ignoredCount?` · 已忽略 ${ignoredCount}`:''}`;reset.hidden=!state.qualityIgnored.size;const counts=new Map();for(const issue of visible)counts.set(issue.type,(counts.get(issue.type)||0)+1);summary.innerHTML=visible.length?QUALITY_TYPE_ORDER.filter(type=>counts.has(type)).map(type=>`<span>${esc(QUALITY_TYPE_LABELS[type])} ${counts.get(type)}</span>`).join(''):'<span>当前没有待检查候选</span>';const visibleIds=new Set(visible.map(issue=>issue.id));const receipts=state.qualityActions.filter(action=>!visibleIds.has(action.issueId)).map(renderQualityActionReceipt).join('');if(!state.sourceCues.length)list.innerHTML='<div class="quality-empty">加载字幕后将按当前编辑态自动检查</div>';else if(!visible.length&&!receipts)list.innerHTML=state.qualityIgnored.size?'<div class="quality-empty">当前候选均已忽略；切换视频或重新加载时会安全清空</div>':'<div class="quality-empty">未发现需要人工复核的字幕候选</div>';else list.innerHTML=visible.map(renderQualityIssue).join('')+receipts;const byId=id=>all.find(issue=>issue.id===id)||null;list.querySelectorAll('[data-quality-locate]').forEach(button=>button.addEventListener('click',()=>{const issue=byId(button.dataset.qualityLocate);if(issue)locateQualityIssue(issue);}));list.querySelectorAll('[data-quality-ignore]').forEach(button=>button.addEventListener('click',()=>ignoreQualityIssue(button.dataset.qualityIgnore)));list.querySelectorAll('[data-quality-action]').forEach(button=>button.addEventListener('click',()=>{const issue=byId(button.dataset.qualityAction);if(issue)executeQualityAction(issue);}));list.querySelectorAll('[data-quality-undo]').forEach(button=>button.addEventListener('click',()=>undoQualityAction(Number(button.dataset.qualityUndo))));}
function locateQualityIssue(issue){const target=Number(issue.primaryIndex);const root=mergeRoot(target);state.filter=state.deleted.has(target)||state.deleted.has(root)?'changed':'all';document.querySelectorAll('#cueFilters button').forEach(button=>button.classList.toggle('active',button.dataset.filter===state.filter));state.selectedCueIndex=root;renderCues();requestAnimationFrame(()=>{const row=document.querySelector(`.cue-row[data-index="${root}"]`);row?.scrollIntoView?.({block:'center',behavior:'smooth'});row?.focus?.({preventScroll:true});});}
function ignoreQualityIssue(issueId){state.qualityIgnored.add(String(issueId));renderQualityList();setTask('已忽略 1 条质检候选；字幕正文和保存内容未改变','done');}
function qualityMapSnapshot(map,key){return{had:map.has(key),value:map.has(key)&&map.get(key)&&typeof map.get(key)==='object'?{...map.get(key)}:map.get(key)};}
function restoreQualityMapSnapshot(map,key,snapshot){if(snapshot.had)map.set(key,snapshot.value&&typeof snapshot.value==='object'?{...snapshot.value}:snapshot.value);else map.delete(key);}
function recordQualityAction(action){state.qualityActions.push({...action,id:++state.qualityActionSerial});return state.qualityActions[state.qualityActions.length-1];}
function executeQualityAction(issue){if(!issue?.action)return false;if(qualityActionForIssue(issue.id)){setTask('该质检建议已经执行，可先撤销','error');return false;}if(issue.action.kind==='preview-delete'){const root=mergeRoot(issue.action.index);if(state.deleted.has(root)){setTask('该字幕已经删除，无法加入删除预览','error');return false;}if(state.deleteSelection.has(root)){setTask('该字幕已在删除预览中，没有重复修改','error');return false;}state.deleteSelection.add(root);recordQualityAction({issueId:issue.id,kind:'preview-delete',root,label:issue.action.label,location:qualityLocationText(issue)});state.selectedCueIndex=root;renderCues();setTask('已加入删除预览，尚未删除字幕；可在质检列表撤销','done');return true;}if(issue.action.kind==='merge'){const leftRoot=mergeRoot(issue.action.left),rightRoot=mergeRoot(issue.action.right);const leftMembers=mergeMembers(leftRoot),rightMembers=mergeMembers(rightRoot);const bridgeFirst=Number(leftMembers[leftMembers.length-1]?.index),bridgeSecond=Number(rightMembers[0]?.index);const snapshots={leftText:qualityMapSnapshot(state.mergeOverrides,leftRoot),rightText:qualityMapSnapshot(state.mergeOverrides,rightRoot),leftTiming:qualityMapSnapshot(state.timeOverrides,leftRoot),rightTiming:qualityMapSnapshot(state.timeOverrides,rightRoot)};if(!Number.isInteger(bridgeFirst)||!Number.isInteger(bridgeSecond)||!mergeGroups(leftRoot,rightRoot)){setTask('当前相邻关系已变化，未执行合并建议','error');return false;}const action=recordQualityAction({issueId:issue.id,kind:'merge',label:issue.action.label,location:qualityLocationText(issue),leftRoot,rightRoot,bridgeFirst,bridgeSecond,...snapshots});action.expectedMembers=mergeMembers(leftRoot).map(cue=>Number(cue.index));action.expectedText=mergedDisplayText(leftRoot);action.expectedTiming={...groupTiming(leftRoot)};state.selectedCueIndex=leftRoot;renderCues();setTask('已合并相邻字幕，尚未保存；可在质检列表撤销','done');return true;}return false;}
function undoQualityAction(actionId){const position=state.qualityActions.findIndex(action=>Number(action.id)===Number(actionId));if(position<0){setTask('没有找到可撤销的质检建议动作','error');return false;}const action=state.qualityActions[position];if(action.kind==='preview-delete'){if(state.deleted.has(action.root)){setTask('删除预览已经确认，质检撤销不会恢复已删除字幕','error');return false;}if(!state.deleteSelection.has(action.root)){state.qualityActions.splice(position,1);renderQualityList();setTask('删除预览已由其他入口取消，已清理陈旧质检记录','done');return true;}state.deleteSelection.delete(action.root);state.qualityActions.splice(position,1);renderCues();setTask('已撤销加入删除预览，字幕正文未改变','done');return true;}if(action.kind==='merge'){if(state.mergePrevious.get(action.bridgeSecond)!==action.bridgeFirst){state.qualityActions.splice(position,1);renderQualityList();setTask('字幕已由其他入口拆开或改变合并关系，已清理陈旧质检记录','done');return true;}const members=mergeMembers(action.leftRoot).map(cue=>Number(cue.index));const timing=groupTiming(action.leftRoot);const unchanged=JSON.stringify(members)===JSON.stringify(action.expectedMembers)&&mergedDisplayText(action.leftRoot)===action.expectedText&&Math.abs(Number(timing.start)-Number(action.expectedTiming.start))<=.0005&&Math.abs(Number(timing.end)-Number(action.expectedTiming.end))<=.0005;if(!unchanged){setTask('合并后已有手工编辑，为保护现有修改未自动撤销','error');return false;}state.mergePrevious.delete(action.bridgeSecond);restoreQualityMapSnapshot(state.mergeOverrides,action.leftRoot,action.leftText);restoreQualityMapSnapshot(state.mergeOverrides,action.rightRoot,action.rightText);restoreQualityMapSnapshot(state.timeOverrides,action.leftRoot,action.leftTiming);restoreQualityMapSnapshot(state.timeOverrides,action.rightRoot,action.rightTiming);state.qualityActions.splice(position,1);state.selectedCueIndex=action.leftRoot;renderCues();setTask('已撤销质检合并建议，原有手工正文和时间状态已保留','done');return true;}return false;}
function cueActionMarkup(label, action, extraClass=''){
    const titles={'merge-previous':'与上一条字幕合并','merge-next':'与下一条字幕合并','unmerge':'拆开当前合并字幕'};
    const title=titles[action]||label;
    return `<button class="cue-action ${extraClass}" type="button" data-action="${action}" title="${title}" aria-label="${title}">${label}</button>`;
}
function renderCueActions(cue, members, merged){
    if(state.deleted.has(cue.index)){
        return '<div class="cue-actions"><button class="cue-delete restore" type="button">恢复</button></div>';
    }
    const rootPosition=cuePosition(cue.index);
    const endCue=members[members.length-1]||cue;
    const endPosition=cuePosition(endCue.index);
    const canMergePrevious=rootPosition>0&&!state.deleted.has(state.sourceCues[rootPosition-1].index);
    const canMergeNext=endPosition>=0&&endPosition<state.sourceCues.length-1&&!state.deleted.has(state.sourceCues[endPosition+1].index);
    const actions=[];
    if(canMergePrevious)actions.push(cueActionMarkup('合上','merge-previous'));
    if(canMergeNext)actions.push(cueActionMarkup('合下','merge-next'));
    if(merged)actions.push(cueActionMarkup('拆开','unmerge','unmerge'));
    actions.push(`<label class="cue-delete-select"><input type="checkbox" data-action="toggle-delete" ${state.deleteSelection.has(Number(cue.index))?'checked':''}>加入删除预览</label>`);
    actions.push('<button class="cue-delete" type="button" data-action="delete">删除</button>');
    return `<div class="cue-actions"><div class="cue-action-group cue-merge-actions">${actions.slice(0,-2).join('')}</div><div class="cue-action-group cue-delete-actions">${actions.slice(-2).join('')}</div></div>`;
}
function renderCueDetail(cue,members,merged){const detailId=`cue-detail-${cue.index}`;if(state.deleted.has(cue.index))return `<div class="cue-detail" id="${detailId}"><div class="cue-time-editor"><span class="cue-label">该字幕已删除，恢复后可继续调整</span></div>${renderCueActions(cue,members,false)}</div>`;const timing=groupTiming(cue.index);return `<div class="cue-detail" id="${detailId}"><div class="cue-time-editor"><div class="cue-time-fields"><label class="cue-time-field">开始时间<input class="cue-time-input" data-time-start type="text" value="${formatSrtTime(timing.start)}" inputmode="decimal" spellcheck="false"></label><label class="cue-time-field">结束时间<input class="cue-time-input" data-time-end type="text" value="${formatSrtTime(timing.end)}" inputmode="decimal" spellcheck="false"></label><button class="cue-action" data-action="reset-time" type="button">恢复原时间</button></div><div class="cue-shift-fields"><label class="cue-time-field">整段移动（秒）<input class="cue-time-input" data-shift-seconds type="number" min="0.01" step="0.1" value="1" inputmode="decimal"></label><div class="cue-shift-actions"><button class="cue-action" data-action="shift-back" type="button">前移</button><button class="cue-action" data-action="shift-forward" type="button">后移</button></div></div><div class="cue-time-error" hidden></div></div>${renderCueActions(cue,members,merged)}</div>`;}
function renderCueAdjustButton(cue,selected){return `<button class="cue-adjust" type="button" data-toggle-cue-detail aria-expanded="${selected}" aria-label="${selected?'收起':'调整'}第 ${cue.index} 条字幕的时间与合并操作">${selected?'收起':'调整'}</button>`;}
function renderCueRow(cue){
    const members=mergeMembers(cue.index);
    const merged=members.length>1;
    const deleted=state.deleted.has(cue.index);
    const endCue=members[members.length-1]||cue;
    const selected=Number(state.selectedCueIndex)===Number(cue.index);
    if(deleted){
        return `<div class="cue-row deleted ${selected?'selected':''}" data-index="${cue.index}" tabindex="0"><span class="cue-spacer" aria-hidden="true"></span><div class="cue-time">${esc(cue.start)}<br>${esc(cue.end)}</div><div class="cue-content"><div class="cue-column"><span class="cue-label">已删除</span><div class="cue-original">${esc(cue.text)}</div></div></div>${renderCueAdjustButton(cue,selected)}${renderCueDetail(cue,members,false)}</div>`;
    }
    const suggestion=merged?null:suggestionFor(cue.index);
    const originalText=members.reduce((text,item)=>joinSubtitleText(text,item.text),'');
    const edited=mergedDisplayText(cue.index);
    const changed=cueChanged(cue);
    const checkbox=merged
        ? '<span class="cue-spacer" aria-hidden="true"></span>'
        : `<input class="cue-check" type="checkbox" ${changed?'checked':''} aria-label="采用第 ${cue.index} 条修改">`;
    const originalLabel=merged?`合并原文（${members.length} 条）`:'识别原文';
    const suggestionMarkup=suggestion
        ? `<div class="cue-reason">${esc(suggestion.reason)}<span class="confidence">${Math.round(Number(suggestion.confidence)*100)}%</span></div>`
        : '';
    const timing=groupTiming(cue.index);
    return `<div class="cue-row ${selected?'selected':''} ${changed?'changed':''} ${suggestion?'suggested':''}" data-index="${cue.index}" tabindex="0">${checkbox}<div class="cue-time">${formatSrtTime(timing.start)}<br>${formatSrtTime(timing.end)}</div><div class="cue-content"><div class="cue-column"><span class="cue-label">${originalLabel}</span><div class="cue-original">${esc(originalText)}</div></div><div class="cue-column"><span class="cue-label">校对后</span><textarea class="cue-edit" rows="1">${esc(edited)}</textarea>${suggestionMarkup}</div></div>${renderCueAdjustButton(cue,selected)}${renderCueDetail(cue,members,merged)}</div>`;
}
function toggleCueDetail(index){const opening=Number(state.selectedCueIndex)!==Number(index);state.selectedCueIndex=opening?Number(index):null;renderCues();}
function wireCueRow(row){
    const index=Number(row.dataset.index);
    const textarea=row.querySelector('.cue-edit');
    const checkbox=row.querySelector('.cue-check');
    row.addEventListener('click',event=>{if(event.target?.closest?.('textarea,input,button,label,a,select'))return;const selection=window.getSelection?.();if(selection?.type==='Range'&&String(selection).trim())return;toggleCueDetail(index);});
    row.addEventListener('keydown',event=>{if(event.target!==row||!['Enter',' '].includes(event.key))return;event.preventDefault();toggleCueDetail(index);});
    row.querySelector('[data-toggle-cue-detail]')?.addEventListener('click',event=>{event.stopPropagation();toggleCueDetail(index);requestAnimationFrame(()=>document.querySelector(`.cue-row[data-index="${index}"] [data-toggle-cue-detail]`)?.focus({preventScroll:true}));});
    if(textarea){
        resizeCueTextarea(textarea);
        textarea.addEventListener('input',()=>{
            resizeCueTextarea(textarea);
            const root=mergeRoot(index);
            if(mergeMembers(root).length>1){
                const defaultText=mergedDefaultText(root);
                if(textarea.value===defaultText)state.mergeOverrides.delete(root);
                else state.mergeOverrides.set(root,textarea.value);
                state.protectedEdits.add(root);
                state.aiApplied.delete(root);
            }else{
                state.protectedEdits.add(index);
                state.aiApplied.delete(index);
                state.edited.set(index,textarea.value);
                if(checkbox)checkbox.checked=textarea.value!==sourceText(index);
                row.classList.toggle('changed',textarea.value!==sourceText(index));
            }
            updateChangeCount();
            scheduleQualityRender();
        });
    }
    if(checkbox)checkbox.addEventListener('change',()=>{
        state.protectedEdits.add(index);
        state.aiApplied.delete(index);
        const suggestion=state.suggestions.get(index);
        const value=checkbox.checked?(suggestion?.corrected??textarea.value):sourceText(index);
        state.edited.set(index,value);
        textarea.value=value;
        resizeCueTextarea(textarea);
        row.classList.toggle('changed',value!==sourceText(index));
        updateChangeCount();
        renderQualityList();
    });
    row.querySelector('[data-action="toggle-delete"]')?.addEventListener('change',event=>{event.stopPropagation();const root=mergeRoot(index);if(event.target.checked)state.deleteSelection.add(root);else state.deleteSelection.delete(root);state.selectedCueIndex=root;renderCues();});
    row.querySelectorAll('.cue-actions button').forEach(button=>button.addEventListener('click',()=>{
        if(button.classList.contains('restore')){restoreCue(index);return;}
        if(button.dataset.action==='merge-previous')mergeWithPrevious(index);
        else if(button.dataset.action==='merge-next')mergeWithNext(index);
        else if(button.dataset.action==='unmerge'){unmergeGroup(index);renderCues();}
        else if(button.dataset.action==='delete')queueCueDelete(index);
        else if(button.dataset.action==='shift-back')shiftCueTiming(index,-1);
        else if(button.dataset.action==='shift-forward')shiftCueTiming(index,1);
    }));
    const startInput=row.querySelector('[data-time-start]');
    const endInput=row.querySelector('[data-time-end]');
    const timeError=row.querySelector('.cue-time-error');
    const commitTiming=()=>{if(!startInput||!endInput)return;const start=parseSrtTime(startInput.value),end=parseSrtTime(endInput.value);const message=start===null||end===null?'请输入 HH:MM:SS,mmm 格式的有效时间':validateTiming(index,start,end);if(message){timeError.textContent=message;timeError.hidden=false;startInput.setAttribute('aria-invalid','true');endInput.setAttribute('aria-invalid','true');return;}const root=mergeRoot(index);const defaults=defaultGroupTiming(root);if(Math.abs(start-defaults.start)<=0.0005&&Math.abs(end-defaults.end)<=0.0005)state.timeOverrides.delete(root);else state.timeOverrides.set(root,{start,end});startInput.setAttribute('aria-invalid','false');endInput.setAttribute('aria-invalid','false');renderCues();};
    startInput?.addEventListener('change',commitTiming);
    endInput?.addEventListener('change',commitTiming);
    row.querySelector('[data-action="reset-time"]')?.addEventListener('click',()=>{state.timeOverrides.delete(mergeRoot(index));renderCues();});
}
function renderCues(){
    const list=document.getElementById('cueList');
    renderSuggestionTools();
    renderQualityList();
    const cues=state.sourceCues.filter(visibleCue);
    if(!cues.length){
        list.innerHTML=renderDeletePreview()||'<div class="queue-empty">当前筛选没有字幕</div>';
        wireDeletePreview(list);
        updateChangeCount();
        return;
    }
    list.innerHTML=`${renderDeletePreview()}${cues.map(renderCueRow).join('')}`;
    wireDeletePreview(list);
    list.querySelectorAll('.cue-row').forEach(wireCueRow);
    updateChangeCount();
}
function deletePreviewEntries(){return [...state.deleteSelection].map(index=>Number(index)).filter(index=>!state.deleted.has(index)).sort((left,right)=>cuePosition(left)-cuePosition(right)).map(root=>{const members=mergeMembers(root);const timing=groupTiming(root);return{root,members,text:mergedDisplayText(root),start:timing.start,end:timing.end};});}
function renderDeletePreview(){const entries=deletePreviewEntries();if(!entries.length)return'';const count=entries.reduce((total,item)=>total+item.members.length,0);const body=entries.map(item=>`<li><span class="cue-delete-preview-text">第 ${item.root} 条${item.members.length>1?`（${item.members.length} 条合并）`:''}：${esc(item.text)}</span><span class="cue-delete-preview-time">${formatSrtTime(item.start)} → ${formatSrtTime(item.end)}</span></li>`).join('');return `<section class="cue-delete-preview" aria-label="删除预览"><div class="cue-delete-preview-head"><strong>删除预览 · ${count} 条</strong><span>确认后仍可在“已改”筛选中恢复</span></div><ul>${body}</ul><div class="cue-delete-preview-actions"><button class="button" type="button" data-action="cancel-delete-preview">取消</button><button class="button danger" type="button" data-action="confirm-delete-preview">确认删除</button></div></section>`;}
function wireDeletePreview(list){const cancel=list.querySelector('[data-action="cancel-delete-preview"]');const confirm=list.querySelector('[data-action="confirm-delete-preview"]');if(cancel?.addEventListener)cancel.addEventListener('click',()=>{state.deleteSelection.clear();renderCues();});if(confirm?.addEventListener)confirm.addEventListener('click',commitPendingDeletes);}
function queueCueDelete(index){const root=mergeRoot(index);state.deleteSelection.add(root);state.selectedCueIndex=root;renderCues();}
function commitPendingDeletes(){const entries=deletePreviewEntries();const count=entries.reduce((total,item)=>total+item.members.length,0);if(!entries.length)return;if(state.deleted.size+count>=state.sourceCues.length){setTask('至少保留一条字幕，无法删除全部字幕','error');return;}for(const item of entries)deleteCue(item.root,false);state.deleteSelection.clear();state.selectedCueIndex=null;renderCues();setTask(`已删除 ${count} 条字幕，可切换“已改”恢复`,'done');}
function deleteCue(index,render=true){const root=mergeRoot(index);const members=mergeMembers(root);const deletedCount=members.length||1;if(state.deleted.size+deletedCount>=state.sourceCues.length){setTask('至少保留一条字幕，无法删除全部字幕','error');return false;}state.deletedSnapshots.set(root,{members:members.map(cue=>Number(cue.index)),mergePrevious:members.slice(1).map((cue,offset)=>({second:Number(cue.index),first:Number(members[offset].index)})),mergeOverride:state.mergeOverrides.get(root),timeOverride:state.timeOverrides.get(root)});unmergeGroup(root,true);for(const cue of members){state.deleted.add(Number(cue.index));state.timeOverrides.delete(Number(cue.index));}state.deleteSelection.delete(root);if(render){state.selectedCueIndex=root;renderCues();}return true;}
function restoreCue(index){if(!state.deleted.has(index))return;let root=Number(index);let snapshot=state.deletedSnapshots.get(root);if(!snapshot){for(const [candidate,value] of state.deletedSnapshots){if(value.members.includes(Number(index))){root=candidate;snapshot=value;break;}}}const members=snapshot?.members||[Number(index)];for(const member of members){state.deleted.delete(member);if(!state.edited.has(member))state.edited.set(member,sourceText(member));}if(snapshot){for(const pair of snapshot.mergePrevious)state.mergePrevious.set(pair.second,pair.first);if(snapshot.mergeOverride!==undefined)state.mergeOverrides.set(root,snapshot.mergeOverride);if(snapshot.timeOverride)state.timeOverrides.set(root,snapshot.timeOverride);state.deletedSnapshots.delete(root);}state.selectedCueIndex=root;renderCues();}
function corrections(){return state.sourceCues.filter(cue=>!state.deleted.has(cue.index)&&(state.edited.get(cue.index)??cue.text)!==cue.text).map(cue=>({index:cue.index,original:cue.text,corrected:state.edited.get(cue.index)}));}
function deletions(){return [...state.deleted].sort((left,right)=>left-right);}
function updateChangeCount(){const correctionCount=corrections().length;const deletionCount=deletions().length;const mergedCount=mergeCount();const timingCount=Object.keys(timeOverrides()).length;const total=correctionCount+deletionCount+mergedCount+timingCount;const details=[];if(deletionCount)details.push(`${deletionCount} 条删除`);if(mergedCount)details.push(`${mergedCount} 处合并`);if(timingCount)details.push(`${timingCount} 条时间调整`);document.getElementById('changeCount').textContent=details.length?`${total} 处变更（${details.join('、')}）`:`${total} 条修改`;}
async function saveCorrections(){const pair=selectedPair();if(!pair)throw new Error('请先选择投稿');persistSubtitleSettings();const confirmed=corrections();const removed=deletions();const pairs=mergePairs();const overrides=mergeOverrides();const timings=timeOverrides();const data=await jsonRequest('/api/subtitles/save',{method:'POST',body:JSON.stringify({srt_path:pair.srt_path,corrections:confirmed,deleted_indices:removed,merge_pairs:pairs,merge_overrides:overrides,time_overrides:timings})});for(const item of confirmed){state.protectedEdits.add(Number(item.index));state.aiApplied.delete(Number(item.index));}state.correctedPath=data.corrected_srt_path;pair.corrected_srt_path=data.corrected_srt_path;pair.has_corrected_srt=true;renderQueue();updateArtifact();return data.corrected_srt_path;}
async function saveClick(){setBusy(true);setTask('保存校对字幕...');try{const correctionCount=corrections().length;const deletionCount=deletions().length;const mergedCount=mergeCount();const timingCount=Object.keys(timeOverrides()).length;await saveCorrections();const details=[`${correctionCount} 条修改`];if(deletionCount)details.push(`删除 ${deletionCount} 条字幕`);if(mergedCount)details.push(`合并 ${mergedCount} 处`);if(timingCount)details.push(`调整 ${timingCount} 条时间`);setTask(`已保存 ${details.join('、')}`,'done');}catch(error){setTask(error.message,'error');}finally{setBusy(false);}}

