[ ['fontColor','fontColorPicker'],['outlineColor','outlineColorPicker'] ].forEach(([textId,pickerId])=>{document.getElementById(textId).addEventListener('input',event=>{if(/^[0-9a-fA-F]{6}$/.test(event.target.value)){document.getElementById(pickerId).value=`#${event.target.value}`;persistSubtitleSettings();}});document.getElementById(pickerId).addEventListener('input',event=>{document.getElementById(textId).value=event.target.value.slice(1);persistSubtitleSettings();});});
['fontSize','outlineWidth','positionX','positionY','bitrate','fps'].forEach(id=>{['input','change'].forEach(eventName=>document.getElementById(id).addEventListener(eventName,()=>{persistSubtitleSettings();if(id==='fontSize'||id==='outlineWidth'){if(eventName==='input')scheduleQualityRender();else renderQualityList();}}));});
window.addEventListener('beforeunload',persistSubtitleSettings);

async function boot(){await Promise.all([loadDefaults(),loadAsrStatus()]);await scan();connectSSE();}
boot();
